from datetime import datetime

from pydantic import BaseModel, Field, field_validator


class RecipeData(BaseModel):
    """A recipe as extracted from one page, before title cleaning."""

    original_name: str
    rating: float | None = None
    votes: int = 0
    ingredients_raw: str
    instructions_raw: str
    extraction_method: str
    raw_jsonld: str | None = None


class ExportRow(BaseModel):
    """One row of the target `recipes` table (id is generated by the database)."""

    title: str = Field(min_length=1)
    original_name: str = Field(min_length=1)
    rating: float | None = Field(default=None, ge=0, le=5)
    votes: int = Field(default=0, ge=0)
    ingredients_raw: str = Field(min_length=1)
    instructions_raw: str = Field(min_length=1)
    source_url: str = Field(pattern=r"^https?://")
    transformed_recipe_id: str | None = None
    created_at: datetime

    @field_validator("title", "original_name", "ingredients_raw", "instructions_raw")
    @classmethod
    def not_blank(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("blank")
        return v.strip()
